args.sql:
SELECT 
  PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY CAST("buyer_risk_profile"->>'behavior_consistency_scr' AS numeric)) as bc_25th
FROM buyers;

SELECT 
  PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY CAST(SPLIT_PART("buyer_risk_profile"->>'risk_dollar_ratio', ' ', 1) AS numeric)) as rd_75th
FROM buyers;

